			ID:             txn1ID,
			IsoLevel:       isolation.Serializable(),
			Epoch:          0,
			WriteTimestamp: ts,
			MinTimestamp:   ts,
			Priority:       roachpb.NormalUserPriority,
		},
		ReadTimestamp:          ts,
		GlobalUncertaintyLimit: ts,
	}

	txn2ID := uuid.MakeV4()
	txn2 := &roachpb.Transaction{
		TxnMeta: enginepb.TxnMeta{
			ID:             txn2ID,
			IsoLevel:       isolation.Serializable(),
			Epoch:          0,
			WriteTimestamp: ts,
			MinTimestamp:   ts,
			Priority:       roachpb.NormalUserPriority,
		},
		ReadTimestamp:          ts,
		GlobalUncertaintyLimit: ts,
